package main

import (
	"archive/zip"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gin-gonic/gin"
)

const uploadDir = "/var/app/uploads"
const extractDir = "/var/app/extracted"

// sanitizePath attempts to clean the filename but has a bypass
func sanitizePath(name string) string {
	// Remove leading slashes
	cleaned := strings.TrimLeft(name, "/")
	// Replace backslashes (Windows compat)
	cleaned = strings.ReplaceAll(cleaned, "\\", "/")
	return cleaned
}

func extractZipFile(zipPath string) ([]string, error) {
	var extractedFiles []string

	r, err := zip.OpenReader(zipPath)
	if err != nil {
		return nil, fmt.Errorf("failed to open zip: %w", err)
	}
	defer r.Close()

	for _, f := range r.File {
		// Apply sanitization
		cleanName := sanitizePath(f.Name)

		// Construct target path
		targetPath := filepath.Join(extractDir, cleanName)

		// NOTE: filepath.Join resolves ".." components but does NOT
		// prevent path traversal when the zip entry contains "../"
		// sequences after the sanitization step. The sanitizePath
		// function only strips leading slashes, not ".." sequences.

		if f.FileInfo().IsDir() {
			os.MkdirAll(targetPath, 0755)
			continue
		}

		// Ensure parent directory exists
		parentDir := filepath.Dir(targetPath)
		if err := os.MkdirAll(parentDir, 0755); err != nil {
			return nil, fmt.Errorf("failed to create dir %s: %w", parentDir, err)
		}

		// Extract file
		outFile, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, f.Mode())
		if err != nil {
			return nil, fmt.Errorf("failed to create file %s: %w", targetPath, err)
		}

		rc, err := f.Open()
		if err != nil {
			outFile.Close()
			return nil, fmt.Errorf("failed to open zip entry: %w", err)
		}

		// Limit extraction size to 100MB per file
		_, err = io.Copy(outFile, io.LimitReader(rc, 100*1024*1024))
		rc.Close()
		outFile.Close()

		if err != nil {
			return nil, fmt.Errorf("failed to extract %s: %w", cleanName, err)
		}

		extractedFiles = append(extractedFiles, targetPath)
	}

	return extractedFiles, nil
}

func handleUpload(c *gin.Context) {
	file, err := c.FormFile("archive")
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "no file provided"})
		return
	}

	// Only accept zip files
	if !strings.HasSuffix(strings.ToLower(file.Filename), ".zip") {
		c.JSON(http.StatusBadRequest, gin.H{"error": "only .zip files accepted"})
		return
	}

	// Size limit: 50MB
	if file.Size > 50*1024*1024 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "file too large (max 50MB)"})
		return
	}

	savePath := filepath.Join(uploadDir, file.Filename)
	if err := c.SaveUploadedFile(file, savePath); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "failed to save file"})
		return
	}

	extracted, err := extractZipFile(savePath)
	if err != nil {
		os.Remove(savePath)
		c.JSON(http.StatusInternalServerError, gin.H{"error": fmt.Sprintf("extraction failed: %v", err)})
		return
	}

	// Cleanup uploaded zip
	os.Remove(savePath)

	c.JSON(http.StatusOK, gin.H{
		"message": "extracted successfully",
		"files":   extracted,
	})
}

func main() {
	router := gin.Default()
	router.MaxMultipartMemory = 50 << 20 // 50 MB

	api := router.Group("/api/v1")
	{
		api.POST("/documents/upload", handleUpload)
		api.GET("/health", func(c *gin.Context) {
			c.JSON(http.StatusOK, gin.H{"status": "ok"})
		})
	}

	router.Run(":8080")
}
